  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, had only 15% oral bioavailability in humans, below the 20% threshold; this illustrates that a lipophilic ester modification does not by itself ensure high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "DEHP, a lipophilic diester, had about 25% oral bioavailability in human volunteers, above the 20% threshold; this is a high-F example among lipophilic esters but lacks the query's beta-lactone scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is orlistat, a pancreatic lipase inhibitor designed to act locally in the GI tract with negligible systemic absorption; its oral bioavailability is far below 20%, so the prediction is low.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule (orlistat) is provided.",
    "No close structural analog with a beta-lactone lipase-inhibitor scaffold is present among the records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

